export type NghiemThuLookupOption = {
  value: string;
  label: string;
};

export type NghiemThuDto = {
  id: string;
  code: string;
  status: string;
  templateType: string;
  route: string;
  zoneOrgCode?: string | null;
  vpOrgCode?: string | null;
  assigneeCode: string;
  inspectedAt: string;
  kmFrom?: number | null;
  kmTo?: number | null;
  fieldInfo: string;
  note?: string | null;
  mediaIds: string[];
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
};

export type NghiemThuPagedResult = {
  items: NghiemThuDto[];
  totalCount: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

export type NghiemThuInitDataDto = {
  statuses: NghiemThuLookupOption[];
  templateTypes: NghiemThuLookupOption[];
};

export const FALLBACK_INIT_DATA: NghiemThuInitDataDto = {
  statuses: [
    { value: 'draft', label: 'Nháp' },
    { value: 'in_progress', label: 'Đang NT' },
    { value: 'done', label: 'Hoàn thành' },
    { value: 'cancelled', label: 'Hủy' },
  ],
  templateTypes: Array.from({ length: 10 }, (_, i) => {
    const n = String(i + 1).padStart(2, '0');
    return { value: `mau-${n}`, label: `Mẫu nghiệm thu ${n}` };
  }),
};

export function statusLabel(
  value: string,
  options: NghiemThuLookupOption[] = FALLBACK_INIT_DATA.statuses,
): string {
  return options.find((o) => o.value === value)?.label ?? value ?? '—';
}

export function templateTypeLabel(
  value: string,
  options: NghiemThuLookupOption[] = FALLBACK_INIT_DATA.templateTypes,
): string {
  return options.find((o) => o.value === value)?.label ?? value ?? '—';
}
