import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useLocation, useParams, useSearchParams } from 'react-router-dom';
import {
  Input,
  LeaveConfirmModal,
  LinImageUpload,
  Select,
  dispatchAppToast,
  useFormLeaveGuard,
  type LinImageUploadItem,
} from '@linm-soft-org/linm-web-common-components';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { RmmsOrgFormFields } from '../../filters/RmmsOrgFormFields';
import {
  EMPTY_RMMS_ORG_FORM,
  orgFromDto,
  orgPersistPayload,
  type RmmsOrgFormValue,
} from '../../filters/rmmsOrgForm';
import { nghiemThuService } from '../../services/nghiemThu/nghiemThuService';
import { nghiemThuListPermissions } from '../../services/nghiemThu/permissions';
import {
  FALLBACK_INIT_DATA,
  type NghiemThuDto,
  type NghiemThuLookupOption,
} from '../../services/nghiemThu/responseModel';
import type { CreateNghiemThuRequest } from '../../services/nghiemThu/requestModel';
import {
  NGHIEM_THU_MEDIA_ACCEPT,
  NGHIEM_THU_MEDIA_LABELS,
  NGHIEM_THU_MEDIA_MAX,
  NGHIEM_THU_VIDEO_MAX_BYTES,
  createNghiemThuMediaUploadApi,
  mediaIdsFromUploadItems,
  uploadItemsFromMediaIds,
} from '../../services/nghiemThu/mediaUpload';
import { buildRmmsDetailToolbar, rmmsFormActionButton } from '../buildRmmsGenericToolbar';
import styles from './NghiemThuFormPage.module.css';

const LIST_PATH = '/nghiem-thu';
const TEST_ID = 'rmms-nghiem-thu-form';
const CREATE_SLUGS = new Set(['new', 'tao-moi']);

export type NghiemThuFormMode = 'create' | 'edit' | 'view' | 'copy';

type FormState = {
  code: string;
  status: string;
  templateType: string;
  zoneOrgCode: string;
  zoneOrgName: string;
  vpOrgCode: string;
  vpOrgName: string;
  assigneeCode: string;
  assigneeName: string;
  routeCode: string;
  routeName: string;
  inspectedAt: string;
  kmFrom: string;
  kmTo: string;
  fieldInfo: string;
  note: string;
  mediaIds: string[];
  updatedAt: string;
};

const emptyForm: FormState = {
  code: '',
  status: '',
  templateType: '',
  ...EMPTY_RMMS_ORG_FORM,
  inspectedAt: '',
  kmFrom: '',
  kmTo: '',
  fieldInfo: '',
  note: '',
  mediaIds: [],
  updatedAt: '',
};

const MODE_TITLE: Record<NghiemThuFormMode, string> = {
  create: 'Thêm nghiệm thu',
  edit: 'Sửa nghiệm thu',
  view: 'Xem nghiệm thu',
  copy: 'Sao chép nghiệm thu',
};

const modeBadge = (mode: NghiemThuFormMode): string => {
  if (mode === 'create' || mode === 'copy') return 'Thêm';
  if (mode === 'view') return 'Xem';
  return 'Sửa';
};

function toDateInput(iso: string): string {
  if (!iso) return '';
  const d = new Date(iso.length === 10 ? `${iso}T00:00:00` : iso);
  if (Number.isNaN(d.getTime())) return iso.slice(0, 10);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function fromDateInput(local: string): string {
  if (!local) return '';
  const d = new Date(`${local}T00:00:00`);
  return Number.isNaN(d.getTime()) ? local : d.toISOString();
}

function formatDateTime(iso: string): string {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

function orgOf(form: FormState): RmmsOrgFormValue {
  return {
    zoneOrgCode: form.zoneOrgCode,
    zoneOrgName: form.zoneOrgName,
    vpOrgCode: form.vpOrgCode,
    vpOrgName: form.vpOrgName,
    assigneeCode: form.assigneeCode,
    assigneeName: form.assigneeName,
    routeCode: form.routeCode,
    routeName: form.routeName,
  };
}

function fromDto(dto: NghiemThuDto, asCopy: boolean): FormState {
  const org = orgFromDto({
    ...dto,
    route: dto.route,
  });
  return {
    code: asCopy ? '' : dto.code,
    status: dto.status,
    templateType: dto.templateType,
    ...org,
    inspectedAt: dto.inspectedAt,
    kmFrom: dto.kmFrom == null ? '' : String(dto.kmFrom),
    kmTo: dto.kmTo == null ? '' : String(dto.kmTo),
    fieldInfo: dto.fieldInfo ?? '',
    note: dto.note ?? '',
    mediaIds: [...(dto.mediaIds ?? [])].slice(0, NGHIEM_THU_MEDIA_MAX),
    updatedAt: asCopy ? '' : dto.updatedAt ?? '',
  };
}

function parseOptionalNumber(raw: string): number | null {
  const t = raw.trim();
  if (!t) return null;
  const n = Number(t);
  return Number.isNaN(n) ? null : n;
}

const NghiemThuFormPage: React.FC = () => {
  const { id } = useParams();
  const { pathname } = useLocation();
  const [searchParams] = useSearchParams();
  const navigate = useInAppNavigate();
  const dispatch = useDispatch();
  const perms = nghiemThuListPermissions();
  const copyFrom = searchParams.get('copyFrom');
  const modeParam = searchParams.get('mode');

  const mode: NghiemThuFormMode = useMemo(() => {
    const isCreatePath =
      pathname.endsWith('/new') ||
      pathname.endsWith('/tao-moi') ||
      !id ||
      CREATE_SLUGS.has(id);
    if (isCreatePath) return copyFrom ? 'copy' : 'create';
    if (modeParam === 'edit') return 'edit';
    if (modeParam === 'copy') return 'copy';
    return 'view';
  }, [id, copyFrom, modeParam, pathname]);

  const readOnly = mode === 'view';
  const [form, setForm] = useState<FormState>(emptyForm);
  const [recordId, setRecordId] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [statuses, setStatuses] = useState<NghiemThuLookupOption[]>(
    FALLBACK_INIT_DATA.statuses,
  );
  const [templateTypes, setTemplateTypes] = useState<NghiemThuLookupOption[]>(
    FALLBACK_INIT_DATA.templateTypes,
  );
  const [mediaItems, setMediaItems] = useState<LinImageUploadItem[]>([]);
  const mediaApi = useMemo(() => createNghiemThuMediaUploadApi(), []);

  useShellPageTitle(MODE_TITLE[mode]);

  const { guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({
    isDirty: !readOnly && dirty,
    title: 'Bạn có dữ liệu chưa lưu',
    message:
      'Tất cả thay đổi chưa được lưu sẽ bị mất. Bạn có chắc muốn rời khỏi trang này không?',
    stayLabel: 'Ở lại trang',
    leaveLabel: 'Rời khỏi trang',
    onBeforeLeave: () => {
      setDirty(false);
    },
  });

  const goList = useCallback(() => {
    guardedNavigate(() => navigate(LIST_PATH));
  }, [guardedNavigate, navigate]);

  const patch = useCallback((partial: Partial<FormState>) => {
    if (readOnly) return;
    setForm((prev) => ({ ...prev, ...partial }));
    setDirty(true);
    setFieldErrors((prev) => {
      const next = { ...prev };
      Object.keys(partial).forEach((k) => {
        delete next[k];
      });
      return next;
    });
  }, [readOnly]);

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      setLoading(true);
      setError(null);
      setFieldErrors({});
      setDirty(false);
      try {
        const init = await nghiemThuService.getInitData();
        if (cancelled) return;
        if (init.statuses?.length) setStatuses(init.statuses);
        if (init.templateTypes?.length) setTemplateTypes(init.templateTypes);

        if (mode === 'create') {
          setRecordId(null);
          setForm({
            ...emptyForm,
            code: '(tự sinh)',
            status: init.statuses?.[0]?.value ?? FALLBACK_INIT_DATA.statuses[0]?.value ?? '',
            templateType:
              init.templateTypes?.[0]?.value ?? FALLBACK_INIT_DATA.templateTypes[0]?.value ?? '',
            inspectedAt: new Date().toISOString(),
          });
          setMediaItems([]);
          return;
        }

        const sourceId = mode === 'copy' ? copyFrom ?? id : id;
        if (!sourceId || CREATE_SLUGS.has(sourceId)) {
          navigate(LIST_PATH);
          return;
        }
        const dto = await nghiemThuService.getById(sourceId);
        if (cancelled) return;
        const next = fromDto(dto, mode === 'copy');
        setRecordId(mode === 'copy' ? null : dto.id);
        setForm(next);
        setMediaItems(uploadItemsFromMediaIds(next.mediaIds));
      } catch (err) {
        if (!cancelled) {
          const msg = err instanceof Error ? err.message : 'Không tải được dữ liệu';
          setError(msg);
          dispatchAppToast(dispatch, { message: msg, type: 'error' });
          navigate(LIST_PATH);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void boot();
    return () => {
      cancelled = true;
    };
  }, [mode, id, copyFrom, navigate, dispatch]);

  const onMediaChange = useCallback(
    (items: LinImageUploadItem[]) => {
      if (readOnly) return;
      setDirty(true);
      setMediaItems(items);
      setForm((prev) => ({ ...prev, mediaIds: mediaIdsFromUploadItems(items) }));
    },
    [readOnly],
  );

  const validate = useCallback((): boolean => {
    const next: Record<string, string> = {};
    if (!form.status) next.status = 'Bắt buộc chọn trạng thái';
    if (!form.templateType) next.templateType = 'Bắt buộc chọn mẫu';
    if (!(form.routeCode || '').trim()) next.routeCode = 'Bắt buộc chọn tuyến';
    if (!(form.assigneeCode || '').trim()) next.assigneeCode = 'Bắt buộc chọn cán bộ';
    if (!form.inspectedAt) next.inspectedAt = 'Bắt buộc nhập ngày nghiệm thu';
    if (!(form.fieldInfo || '').trim()) next.fieldInfo = 'Bắt buộc nhập thông tin hiện trường';
    if (form.kmFrom.trim() && Number.isNaN(Number(form.kmFrom))) {
      next.kmFrom = 'Km đầu phải là số';
    }
    if (form.kmTo.trim() && Number.isNaN(Number(form.kmTo))) {
      next.kmTo = 'Km cuối phải là số';
    }
    setFieldErrors(next);
    return Object.keys(next).length === 0;
  }, [form]);

  const handleSave = useCallback(async () => {
    if (readOnly) return;
    if ((mode === 'create' || mode === 'copy') && !perms.canCreate) {
      dispatchAppToast(dispatch, { message: 'Không có quyền thêm', type: 'warning' });
      return;
    }
    if (mode === 'edit' && !perms.canUpdate) {
      dispatchAppToast(dispatch, { message: 'Không có quyền sửa', type: 'warning' });
      return;
    }
    if (!validate()) return;

    setSaving(true);
    setError(null);
    const org = orgPersistPayload(orgOf(form));
    const mediaIds = mediaIdsFromUploadItems(mediaItems);
    const body: CreateNghiemThuRequest = {
      status: form.status,
      templateType: form.templateType,
      route: (form.routeCode || '').trim(),
      zoneOrgCode: org.zoneOrgCode ?? null,
      vpOrgCode: org.vpOrgCode ?? null,
      assigneeCode: (form.assigneeCode || '').trim(),
      inspectedAt: form.inspectedAt.includes('T')
        ? form.inspectedAt
        : fromDateInput(toDateInput(form.inspectedAt)),
      kmFrom: parseOptionalNumber(form.kmFrom),
      kmTo: parseOptionalNumber(form.kmTo),
      fieldInfo: form.fieldInfo.trim(),
      note: form.note.trim() || null,
      mediaIds,
    };

    try {
      if (mode === 'edit' && recordId) {
        await nghiemThuService.update(recordId, body);
        setDirty(false);
        dispatchAppToast(dispatch, { message: 'Đã lưu nghiệm thu', type: 'success' });
        navigate(LIST_PATH);
      } else {
        const dto = await nghiemThuService.create(body);
        setDirty(false);
        dispatchAppToast(dispatch, { message: 'Đã tạo nghiệm thu', type: 'success' });
        navigate(`${LIST_PATH}/${dto.id}`, { replace: true });
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Lưu thất bại';
      setError(msg);
      dispatchAppToast(dispatch, { message: msg, type: 'error' });
    } finally {
      setSaving(false);
    }
  }, [
    readOnly,
    mode,
    perms.canCreate,
    perms.canUpdate,
    validate,
    form,
    mediaItems,
    recordId,
    dispatch,
    navigate,
  ]);

  const statusSelectOptions = useMemo(
    () => statuses.map((o) => ({ value: o.value, label: o.label })),
    [statuses],
  );
  const templateSelectOptions = useMemo(
    () => templateTypes.map((o) => ({ value: o.value, label: o.label })),
    [templateTypes],
  );

  const rightActions = readOnly ? (
    <>
      {perms.canUpdate && recordId
        ? rmmsFormActionButton({
            testId: `${TEST_ID}-btn-to-edit`,
            label: 'Sửa',
            icon: 'fas fa-pen',
            onClick: () =>
              navigate(`${LIST_PATH}/${encodeURIComponent(recordId)}?mode=edit`),
          })
        : null}
      {perms.canCreate && recordId
        ? rmmsFormActionButton({
            testId: `${TEST_ID}-btn-to-copy`,
            label: 'Sao chép',
            icon: 'fas fa-copy',
            onClick: () =>
              navigate(`${LIST_PATH}/new?copyFrom=${encodeURIComponent(recordId)}`),
          })
        : null}
    </>
  ) : (
    <>
      {rmmsFormActionButton({
        testId: `${TEST_ID}-btn-cancel`,
        label: 'Hủy',
        icon: 'fas fa-times',
        onClick: goList,
      })}
      {rmmsFormActionButton({
        testId: `${TEST_ID}-btn-save`,
        label: saving ? 'Đang lưu…' : 'Lưu',
        icon: 'fas fa-save',
        variant: 'primary',
        onClick: () => void handleSave(),
        loading: saving,
      })}
    </>
  );

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      {buildRmmsDetailToolbar({
        testIdPrefix: TEST_ID,
        onBack: goList,
        right: rightActions,
      })}
      <div className={styles.headingRow}>
        <h1 className={styles.heading}>{MODE_TITLE[mode]}</h1>
        <span className={styles.badge}>{modeBadge(mode)}</span>
      </div>
      {error ? (
        <div className={styles.errorBanner} data-testid={`${TEST_ID}-error`}>
          {error}
        </div>
      ) : null}
      {loading ? (
        <div data-testid={`${TEST_ID}-loading`}>Đang tải…</div>
      ) : (
        <div className={styles.card}>
          <div className={styles.fields} data-form-cols="5">
            <div data-testid={`${TEST_ID}-field-code`}>
              <Input
                label="Mã nghiệm thu"
                value={form.code || (mode === 'create' || mode === 'copy' ? '(tự sinh)' : '')}
                readOnly
                disabled
                fullWidth
                data-testid={`${TEST_ID}-code`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-status`}>
              <Select
                label="Trạng thái"
                value={form.status}
                options={statusSelectOptions}
                onChange={(e) => patch({ status: String(e.target.value ?? '') })}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-status`}
              />
              {fieldErrors.status ? (
                <div className={styles.fieldError}>{fieldErrors.status}</div>
              ) : null}
            </div>
            <div data-testid={`${TEST_ID}-field-templateType`}>
              <Select
                label="Mẫu nghiệm thu"
                value={form.templateType}
                options={templateSelectOptions}
                onChange={(e) => patch({ templateType: String(e.target.value ?? '') })}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-templateType`}
              />
              {fieldErrors.templateType ? (
                <div className={styles.fieldError}>{fieldErrors.templateType}</div>
              ) : null}
            </div>
            <RmmsOrgFormFields
              testIdPrefix={TEST_ID}
              value={orgOf(form)}
              disabled={readOnly}
              routeRequired
              routeError={fieldErrors.routeCode}
              onChange={(next) => {
                patch({
                  zoneOrgCode: next.zoneOrgCode,
                  zoneOrgName: next.zoneOrgName,
                  vpOrgCode: next.vpOrgCode,
                  vpOrgName: next.vpOrgName,
                  assigneeCode: next.assigneeCode,
                  assigneeName: next.assigneeName,
                  routeCode: next.routeCode,
                  routeName: next.routeName,
                });
              }}
            />
            {fieldErrors.assigneeCode ? (
              <div className={styles.fieldError} data-testid={`${TEST_ID}-assignee-error`}>
                {fieldErrors.assigneeCode}
              </div>
            ) : null}
            <div data-testid={`${TEST_ID}-field-inspectedAt`}>
              <Input
                label="Ngày nghiệm thu"
                type="date"
                required
                value={toDateInput(form.inspectedAt)}
                onChange={(e) => patch({ inspectedAt: fromDateInput(e.target.value) })}
                readOnly={readOnly}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-inspectedAt`}
              />
              {fieldErrors.inspectedAt ? (
                <div className={styles.fieldError}>{fieldErrors.inspectedAt}</div>
              ) : null}
            </div>
            <div data-testid={`${TEST_ID}-field-kmFrom`}>
              <Input
                label="Km đầu"
                type="number"
                value={form.kmFrom}
                onChange={(e) => patch({ kmFrom: e.target.value })}
                readOnly={readOnly}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-kmFrom`}
              />
              {fieldErrors.kmFrom ? (
                <div className={styles.fieldError}>{fieldErrors.kmFrom}</div>
              ) : null}
            </div>
            <div data-testid={`${TEST_ID}-field-kmTo`}>
              <Input
                label="Km cuối"
                type="number"
                value={form.kmTo}
                onChange={(e) => patch({ kmTo: e.target.value })}
                readOnly={readOnly}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-kmTo`}
              />
              {fieldErrors.kmTo ? (
                <div className={styles.fieldError}>{fieldErrors.kmTo}</div>
              ) : null}
            </div>
            <div className={styles.span2} data-testid={`${TEST_ID}-field-fieldInfo`}>
              <Input
                label="Thông tin hiện trường"
                value={form.fieldInfo}
                onChange={(e) => patch({ fieldInfo: e.target.value })}
                readOnly={readOnly}
                disabled={readOnly}
                required
                fullWidth
                data-testid={`${TEST_ID}-fieldInfo`}
              />
              {fieldErrors.fieldInfo ? (
                <div className={styles.fieldError}>{fieldErrors.fieldInfo}</div>
              ) : null}
            </div>
            <div className={styles.span2} data-testid={`${TEST_ID}-field-note`}>
              <Input
                label="Ghi chú"
                value={form.note}
                onChange={(e) => patch({ note: e.target.value })}
                readOnly={readOnly}
                disabled={readOnly}
                fullWidth
                data-testid={`${TEST_ID}-note`}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-updatedAt`}>
              <Input
                label="Cập nhật"
                value={form.updatedAt ? formatDateTime(form.updatedAt) : '—'}
                readOnly
                disabled
                fullWidth
                data-testid={`${TEST_ID}-updatedAt`}
              />
            </div>
            <div className={styles.spanFull} data-zone="upload" data-testid={`${TEST_ID}-upload`}>
              <LinImageUpload
                purpose="nghiem-thu-media"
                product="rmms"
                entityType="nghiem_thu"
                entityId={recordId ?? undefined}
                items={mediaItems}
                onChange={onMediaChange}
                maxFiles={NGHIEM_THU_MEDIA_MAX}
                maxBytes={NGHIEM_THU_VIDEO_MAX_BYTES}
                accept={NGHIEM_THU_MEDIA_ACCEPT}
                disabled={readOnly}
                confirmRemove={mode === 'edit'}
                labels={NGHIEM_THU_MEDIA_LABELS}
                client={mediaApi}
                testId={`${TEST_ID}-field-mediaIds`}
              />
            </div>
          </div>
        </div>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default NghiemThuFormPage;
