import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import type {
  NghiemThuDto,
  NghiemThuInitDataDto,
  NghiemThuPagedResult,
} from './responseModel';
import type { CreateNghiemThuRequest, UpdateNghiemThuRequest } from './requestModel';

/** Relative to VITE_API_URL (already includes /api/v1 or web-bff/api/v1). */
const BASE = '/patrol/nghiem-thu';

type PagedEnvelope = {
  items?: NghiemThuDto[];
  totalCount?: number;
  page?: number;
  pageSize?: number;
  totalPages?: number;
};

function normalizePaged(
  raw: PagedEnvelope | NghiemThuDto[] | null | undefined,
): NghiemThuPagedResult {
  if (Array.isArray(raw)) {
    return {
      items: raw,
      totalCount: raw.length,
      page: 1,
      pageSize: raw.length || 50,
      totalPages: 1,
    };
  }
  const items = raw?.items ?? [];
  const totalCount = raw?.totalCount ?? items.length;
  const page = raw?.page ?? 1;
  const pageSize = raw?.pageSize ?? 50;
  const totalPages =
    raw?.totalPages ?? Math.max(1, Math.ceil(totalCount / Math.max(pageSize, 1)));
  return { items, totalCount, page, pageSize, totalPages };
}

export const nghiemThuEndpoint = {
  getList: async (params?: {
    search?: string;
    status?: string;
    route?: string;
    templateType?: string;
    fromDate?: string;
    toDate?: string;
    page?: number;
    pageSize?: number;
  }) => {
    const qs = new URLSearchParams();
    if (params?.search) qs.set('search', params.search);
    if (params?.status) qs.set('status', params.status);
    if (params?.route) qs.set('route', params.route);
    if (params?.templateType) qs.set('templateType', params.templateType);
    if (params?.fromDate) qs.set('fromDate', params.fromDate);
    if (params?.toDate) qs.set('toDate', params.toDate);
    qs.set('page', String(params?.page ?? 1));
    qs.set('pageSize', String(params?.pageSize ?? 50));
    const res = await apiClient.get<BffResponse<PagedEnvelope | NghiemThuDto[]>>(
      `${BASE}?${qs}`,
    );
    return normalizePaged(unwrap(res));
  },

  getInitData: async () => {
    const res = await apiClient.get<BffResponse<NghiemThuInitDataDto>>(
      `${BASE}/init-data`,
    );
    return unwrap(res);
  },

  getById: async (id: string) => {
    const res = await apiClient.get<BffResponse<NghiemThuDto>>(`${BASE}/${id}`);
    return unwrap(res);
  },

  create: async (data: CreateNghiemThuRequest) => {
    const res = await apiClient.post<BffResponse<NghiemThuDto>>(BASE, data);
    return unwrap(res);
  },

  update: async (id: string, data: UpdateNghiemThuRequest) => {
    const res = await apiClient.put<BffResponse<NghiemThuDto>>(`${BASE}/${id}`, data);
    return unwrap(res);
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`${BASE}/${id}`);
  },
};
